mapper.select:
SELECT id, user_id, token_hash, family_id, device_id, device_name, expires_at,
       revoked_at, revoked_reason, replaced_by_id, create_time
FROM app_refresh_session WHERE token_hash = #{tokenHash}

SELECT id, user_id, token_hash, family_id, device_id, device_name, expires_at,
       revoked_at, revoked_reason, replaced_by_id, create_time
FROM app_refresh_session WHERE id = #{id}

mapper.update:
UPDATE app_refresh_session
SET revoked_at = #{now}, revoked_reason = #{reason}, update_time = #{now}
WHERE id = #{id} AND revoked_at IS NULL

UPDATE app_refresh_session
SET replaced_by_id = #{replacedById}, update_time = NOW()
WHERE id = #{id}

UPDATE app_refresh_session
SET revoked_at = #{now}, revoked_reason = #{reason}, update_time = #{now}
WHERE family_id = #{familyId} AND revoked_at IS NULL

UPDATE app_refresh_session
SET revoked_at = #{now}, revoked_reason = #{reason}, update_time = #{now}
WHERE user_id = #{userId} AND revoked_at IS NULL

UPDATE app_refresh_session
SET revoked_at = #{now}, revoked_reason = #{reason}, update_time = #{now}
WHERE user_id = #{userId} AND revoked_at IS NULL

    AND id != #{keepId}
